/* Tutorial engine.
 *
 * A lesson (window.LESSON) is a list of steps: read, mcq, numeric, match.
 * An mcq option may carry `why`, the reason that option is tempting but wrong; a student who
 * picks it sees the reason above the step's worked explanation, and a screen reader hears it
 * after the verdict.
 * The lock (window.LOCK, generated by tools/build_lock.mjs) holds:
 *   - salted SHA-256 hashes of the correct answers, so answers are checked
 *     without storing them in plain text;
 *   - each student's magic word, AES-GCM encrypted with a key derived from
 *     their CNetID plus the correct answers to every question.
 * The word can only be decrypted by answering every question correctly.
 * Answer parsing and canonicalization come from core.js (window.CORE), shared with the build.
 */
(() => {
  "use strict";
  const L = window.LESSON;
  const K = window.LOCK;
  const W = window.WIDGETS || {};
  const { normalizeId, parseNumber, canonNumber, texToText } = window.CORE;
  const enc = new TextEncoder();
  const STORE = `bayes-tutorial-${L.id}-${K.salt.slice(0, 8)}`;
  const QTYPES = new Set(["mcq", "numeric", "match"]);
  const CONFETTI = ["#FFA319", "#FFB547", "#D49464", "#6FA0B8", "#ADB17D", "#F7EEE3"];

  // ---------------------------------------------------------------- helpers
  function el(tag, attrs = {}, ...kids) {
    const n = document.createElement(tag);
    for (const [k, v] of Object.entries(attrs)) {
      if (v == null || v === false) continue;
      if (k === "class") n.className = v;
      else if (k === "html") n.innerHTML = v;
      else if (k.startsWith("on")) n.addEventListener(k.slice(2), v);
      else n.setAttribute(k, v === true ? "" : v);
    }
    for (const kid of kids.flat()) if (kid != null) n.append(kid.nodeType ? kid : document.createTextNode(kid));
    return n;
  }
  const hex = (buf) => [...new Uint8Array(buf)].map((b) => b.toString(16).padStart(2, "0")).join("");
  const sha256 = async (s) => hex(await crypto.subtle.digest("SHA-256", enc.encode(s)));
  const answerHash = (qid, value) => sha256(`${K.salt}|${qid}|${value}`);
  const idHash = (cnetid) => sha256(`${K.salt}|id|${cnetid}`);
  const b64 = (s) => Uint8Array.from(atob(s), (c) => c.charCodeAt(0));

  function math(root) {
    if (window.renderMathInElement) {
      window.renderMathInElement(root, {
        delimiters: [{ left: "$$", right: "$$", display: true }, { left: "$", right: "$", display: false }],
        ignoredClasses: ["nomath"],
        throwOnError: false,
      });
    }
  }
  const reducedMotion = () => window.matchMedia("(prefers-reduced-motion: reduce)").matches;

  function mountVisual(container, visual, ctx) {
    if (!visual) return;
    const fn = W[visual.widget];
    if (!fn) { console.error(`Tutorial engine: widget "${visual.widget}" is not loaded on this page`); return; }
    fn(container, visual.props || {}, ctx);
  }

  // ---------------------------------------------------------------- state
  const questionIds = L.steps.filter((s) => QTYPES.has(s.type)).map((s) => s.id);
  let S = load();

  function fresh(cnetid) {
    return {
      cnetid, queue: L.steps.map((_, i) => i), pos: 0,
      done: {}, solved: {}, retried: {}, firstTry: 0,
      startedAt: Date.now(), finishedAt: null, word: null,
    };
  }
  function load() {
    try { return JSON.parse(localStorage.getItem(STORE)); } catch { return null; }
  }
  function save() { try { localStorage.setItem(STORE, JSON.stringify(S)); } catch { /* private mode */ } }

  // ---------------------------------------------------------------- layout
  const app = document.getElementById("app");
  let footer, footerInner, stageEl, progressFill, countEl, announcer;
  let keyHandler = null;

  function setKeys(fn) {
    if (keyHandler) document.removeEventListener("keydown", keyHandler);
    keyHandler = fn;
    if (fn) document.addEventListener("keydown", fn);
  }

  function shell() {
    app.innerHTML = "";
    progressFill = el("span");
    countEl = el("div", { class: "count", "aria-live": "polite" });
    const top = el("header", { class: "topbar" },
      el("button", { class: "icon-btn", "aria-label": "Save and exit", title: "Save and exit", onclick: () => { save(); intro(); } },
        el("span", { html: '<svg width="18" height="18" viewBox="0 0 20 20" aria-hidden="true"><path d="M4 4l12 12M16 4L4 16" stroke="currentColor" stroke-width="2" stroke-linecap="round"/></svg>' })),
      el("div", { class: "progress", role: "progressbar", "aria-label": "Progress", "aria-valuemin": "0", "aria-valuemax": "100" }, progressFill),
      countEl);
    stageEl = el("main", { class: "stage", id: "stage" });
    footerInner = el("div", { class: "footer-inner" });
    footer = el("footer", { class: "footer" }, footerInner);
    // Screen readers can miss a live region that arrives with its text already inside, so the
    // footer is rebuilt without one and every result is announced here instead.
    announcer = el("div", { class: "sr-only", id: "announcer", "aria-live": "polite" });
    app.append(top, stageEl, footer, announcer);
    updateTop();
  }

  function updateTop(idx) {
    const total = L.steps.length;
    const done = Object.keys(S.done).length;
    const pct = Math.round((done / total) * 100);
    progressFill.style.width = `${pct}%`;
    progressFill.parentElement.setAttribute("aria-valuenow", String(pct));
    if (idx != null) countEl.textContent = `${idx + 1} / ${total}`;
  }

  function setFooter({ state = "", title = "", text = "", button, onClick, disabled = false, extra = null }) {
    footer.className = "footer" + (state ? ` is-${state} is-open` : "");
    footerInner.innerHTML = "";
    const fb = el("div", { class: "feedback" });
    if (title) fb.append(el("h3", {}, title));
    if (text) { const t = el("div", { class: "fb-text", html: text }); fb.append(t); math(t); }
    if (extra) fb.append(extra);
    const btn = el("button", { class: "btn" + (state ? ` ${state}` : ""), onclick: onClick }, button);
    btn.disabled = disabled;
    footerInner.append(fb, btn);
    return btn;
  }

  // ---------------------------------------------------------------- intro
  function intro() {
    setKeys(null);
    app.innerHTML = "";
    const started = S && S.pos > 0;
    const finished = S && S.word;
    const wrap = el("main", { class: "intro" });
    wrap.append(
      el("div", { class: "kicker" }, L.kicker),
      el("h1", {}, L.title),
      el("p", { class: "lede", html: L.lede }),
    );
    if (L.introVisual) {
      const v = el("div", { class: "intro-visual" });
      wrap.append(v);
      mountVisual(v, L.introVisual, { setReady() {}, math });
    }
    const path = el("ol", { class: "path", "aria-label": "What you'll cover" });
    L.units.forEach((u, i) => {
      const unitSteps = L.steps.map((s, idx) => [s, idx]).filter(([s]) => s.unit === u.id);
      const complete = S && unitSteps.every(([, idx]) => S.done[idx]);
      path.append(el("li", { class: complete ? "is-done" : "" }, el("span", { class: "dot" }, complete ? "✓" : String(i + 1)), u.title));
    });
    wrap.append(path);

    const form = el("form", { class: "signin", onsubmit: (e) => { e.preventDefault(); begin(); } });
    const input = el("input", { id: "cnetid", name: "cnetid", autocomplete: "username", autocapitalize: "none", spellcheck: "false", required: true, placeholder: "e.g. jdoe" });
    if (S && S.cnetid) input.value = S.cnetid;
    const warn = el("div", { class: "warn", hidden: true });
    const startBtn = el("button", { class: "btn", type: "submit" }, finished ? "See my magic word" : started ? "Continue where I left off" : "Start");
    form.append(
      el("label", { for: "cnetid" }, "Your CNetID"),
      input,
      el("div", { class: "note" }, "Your magic word is tied to your CNetID. Progress saves in this browser."),
      warn,
      el("div", { class: "row" }, startBtn,
        started ? el("button", { type: "button", class: "linklike", onclick: () => { if (confirm("Start over from the beginning? Your progress in this browser will be cleared.")) { S = null; localStorage.removeItem(STORE); intro(); } } }, "Start over") : null),
    );
    wrap.append(form);
    app.append(wrap);
    math(wrap);

    async function begin() {
      const id = normalizeId(input.value);
      if (!/^[a-z0-9._-]{2,}$/.test(id)) {
        warn.hidden = false; warn.textContent = "Enter your CNetID: letters and numbers, like jdoe.";
        return;
      }
      const known = Boolean(K.table[await idHash(id)]);
      if (!known && warn.dataset.acknowledged !== id) {
        warn.hidden = false;
        warn.dataset.acknowledged = id;
        warn.textContent = `We don't have a magic word for "${id}" yet. Check the spelling of your CNetID. If it's right, you can still do the tutorial; email the TA so we can add you. Press the button again to continue.`;
        return;
      }
      if (!S || S.cnetid !== id) {
        const keep = S && S.cnetid !== id && S.pos > 0 ? S : null;
        S = keep ? { ...keep, cnetid: id, word: null } : fresh(id);
      }
      save();
      if (S.word || S.pos >= S.queue.length) finish(); else { shell(); step(); }
    }
  }

  // ---------------------------------------------------------------- steps
  function step() {
    // Skip queued retries of steps that were already completed (e.g. after a reload).
    while (S.pos < S.queue.length && S.done[S.queue[S.pos]] !== undefined && S.queue.indexOf(S.queue[S.pos]) !== S.pos) S.pos += 1;
    if (S.pos >= S.queue.length) return finish();
    const idx = S.queue[S.pos];
    const s = L.steps[idx];
    updateTop(idx);
    // Emptied for each step, so a result is new text even when it matches the last one.
    announcer.textContent = "";
    stageEl.innerHTML = "";
    stageEl.style.paddingBottom = "";
    window.scrollTo({ top: 0 });
    const unit = L.units.find((u) => u.id === s.unit);
    if (unit) stageEl.append(el("div", { class: "unit-label" }, unit.title));
    if (S.done[idx] === undefined && S.retried[idx]) stageEl.append(el("div", { class: "retry-note" }, "Second try"));
    if (s.title) stageEl.append(el("h2", { class: "prompt" }, s.title));
    const ctx = { ready: true, label: null, onReady: null, setReady(flag, label) { this.ready = flag; this.label = label || null; if (this.onReady) this.onReady(); }, math };
    if (s.visual) {
      const v = el("div", { class: "visual" });
      stageEl.append(v);
      mountVisual(v, s.visual, ctx);
    }
    if (s.html) stageEl.append(el("div", { class: "body-text", html: s.html }));
    ({ read: readStep, mcq: mcqStep, numeric: numericStep, match: matchStep })[s.type](s, idx, ctx);
    math(stageEl);
    // Move focus to the new step so keyboard and screen-reader users land on it; number steps
    // focus their answer box instead, which is described by the question.
    const heading = stageEl.querySelector(".prompt");
    if (heading && s.type !== "numeric") {
      heading.setAttribute("tabindex", "-1");
      heading.focus({ preventScroll: true });
    }
  }

  function advance() {
    S.pos += 1;
    save();
    step();
  }

  function markDone(idx, qid, canonical, firstTry) {
    if (qid) S.solved[qid] = canonical;
    if (S.done[idx] === undefined) {
      S.done[idx] = true;
      if (qid && firstTry) S.firstTry += 1;
    }
    save();
    updateTop();
  }

  function praise() {
    const lines = ["Nice work.", "Correct.", "Exactly right.", "You got it.", "Spot on."];
    return lines[Math.floor(Math.random() * lines.length)];
  }

  // read ---------------------------------------------------------------
  function readStep(s, idx, ctx) {
    const go = () => { if (S.done[idx] === undefined) { S.done[idx] = true; save(); updateTop(); } advance(); };
    const render = () => {
      const btn = setFooter({ button: ctx.ready ? (s.button || "Continue") : (ctx.label || "Continue"), onClick: go, disabled: !ctx.ready });
      setKeys((e) => { if (e.key === "Enter" && ctx.ready && document.activeElement?.tagName !== "BUTTON") go(); });
      return btn;
    };
    ctx.onReady = render;
    render();
  }

  // shared question footer -----------------------------------------------
  function resolve({ good, idx, s, canonical, explainGood, explainBad }) {
    const firstTry = !S.retried[idx];
    let btn;
    if (good) {
      markDone(idx, s.id, canonical, firstTry);
      btn = setFooter({ state: "good", title: praise(), text: explainGood || "", button: "Continue", onClick: advance });
    } else {
      S.retried[idx] = true;
      S.queue.push(idx);
      save();
      btn = setFooter({ state: "bad", title: "Not quite", text: (explainBad || "") + '<p style="margin-top:.5em"><b>You\'ll see this question again at the end.</b></p>', button: "Continue", onClick: advance });
    }
    btn.focus();
    keepAnswerInView();
    // Announced once focus is on Continue, because a later focus move can cut it short.
    announceResult();
    setKeys((e) => { if (e.key === "Enter") { e.preventDefault(); advance(); } });
  }

  // The verdict, then the reason for a wrong option if it has one: "Not quite. 3/4 is ...".
  function announceResult() {
    const title = footer.querySelector(".feedback h3").textContent;
    const verdict = /[.!?]$/.test(title) ? title : `${title}.`;
    const why = footer.querySelector(".why");
    announcer.textContent = why ? `${verdict} ${spoken(why).trim()}` : verdict;
  }

  // What a screen reader should hear for rendered lesson HTML. KaTeX writes each formula twice,
  // as MathML and as an aria-hidden drawing, and stacked fractions hide their drawing too, so
  // hidden parts are skipped and each formula is read from its TeX source.
  function spoken(node) {
    if (node.nodeType === Node.TEXT_NODE) return node.nodeValue;
    if (node.nodeType !== Node.ELEMENT_NODE || node.getAttribute("aria-hidden") === "true") return "";
    const tex = node.classList.contains("katex-mathml") ? node.querySelector("annotation") : null;
    if (tex) return texToText(tex.textContent);
    return [...node.childNodes].map(spoken).join("").replace(/\s+/g, " ");
  }

  // The open feedback sheet can be tall on a phone. Make room for it below the stage and
  // scroll the correct answer, marked in green, above it.
  function keepAnswerInView() {
    const h = footer.getBoundingClientRect().height;
    stageEl.style.paddingBottom = `${Math.ceil(h) + 24}px`;
    const target = stageEl.querySelector(".tile.is-good") || stageEl.querySelector(".num-input, .match");
    if (!target) return;
    const limit = window.innerHeight - h - 12;
    const r = target.getBoundingClientRect();
    if (r.bottom > limit) window.scrollBy({ top: r.bottom - limit, behavior: reducedMotion() ? "auto" : "smooth" });
  }

  // mcq ------------------------------------------------------------------
  function mcqStep(s, idx) {
    if (s.prompt) stageEl.append(el("p", { class: "body-text", html: s.prompt }));
    // Short answers such as fractions sit two to a row with `columns: 2`.
    const group = el("div", { class: s.columns === 2 ? "options two-up" : "options", role: "radiogroup", "aria-label": "Answer choices" });
    let choice = null;
    const tiles = s.options.map((o, i) => {
      const t = el("button", { class: "tile", role: "radio", "aria-checked": "false", "data-id": o.id, onclick: () => pick(o.id) },
        el("span", { class: "key" }, String(i + 1)), el("span", { html: o.html }));
      group.append(t);
      return t;
    });
    stageEl.append(group);
    const check = () => setFooter({ button: "Check", onClick: submit, disabled: !choice });
    function pick(id) {
      choice = id;
      tiles.forEach((t) => t.setAttribute("aria-checked", String(t.dataset.id === id)));
      check();
    }
    check();
    setKeys((e) => {
      const n = Number(e.key);
      if (n >= 1 && n <= tiles.length) pick(s.options[n - 1].id);
      else if (e.key === "Enter" && choice) { e.preventDefault(); submit(); }
    });
    async function submit() {
      if (!choice) return;
      const good = (await answerHash(s.id, choice)) === K.answers[s.id];
      tiles.forEach((t) => { t.disabled = true; });
      const chosen = tiles.find((t) => t.dataset.id === choice);
      if (good) chosen.classList.add("is-good");
      else {
        chosen.classList.add("is-bad");
        for (const t of tiles) if ((await answerHash(s.id, t.dataset.id)) === K.answers[s.id]) t.classList.add("is-good");
      }
      const why = s.options.find((o) => o.id === choice).why;
      const worked = s.explainWrong || s.explain || "";
      resolve({ good, idx, s, canonical: choice, explainGood: s.explain, explainBad: why ? `<p class="why">${why}</p>${worked}` : worked });
    }
  }

  // numeric --------------------------------------------------------------
  function numericStep(s, idx) {
    // The question text describes the answer box, so a screen reader reads it with the box.
    const questionId = `question-${idx}`;
    if (s.prompt) stageEl.append(el("p", { class: "body-text", id: questionId, html: s.prompt }));
    else stageEl.querySelector(".prompt")?.setAttribute("id", questionId);
    // No inputmode: phone keypads for "decimal" have no "/" and may only offer ",".
    const input = el("input", { class: "num-input", type: "text", autocomplete: "off", autocapitalize: "off", autocorrect: "off", spellcheck: "false", enterkeyhint: "done", "aria-label": "Your answer", "aria-describedby": questionId, placeholder: s.placeholder || "0.00" });
    stageEl.append(el("div", { class: "num-row" }, input, s.unitLabel ? el("span", {}, s.unitLabel) : null));
    stageEl.append(el("div", { class: "hint" }, s.hint || "A fraction like 3/8 or a decimal like 0.38."));
    const error = el("div", { class: "num-error", role: "status", hidden: true }, "That doesn't read as a number yet. Try something like 0.38 or 3/8.");
    stageEl.append(error);
    // Explain an unreadable answer only after a pause, so a half-typed "3/" does not flash a warning.
    let pause = null;
    const unreadable = () => input.value.trim() !== "" && parseNumber(input.value) === null;
    const check = () => {
      clearTimeout(pause);
      error.hidden = true;
      if (unreadable()) pause = setTimeout(() => { error.hidden = !unreadable(); }, 700);
      setFooter({ button: "Check", onClick: submit, disabled: parseNumber(input.value) === null });
    };
    input.addEventListener("input", check);
    check();
    setTimeout(() => input.focus(), 30);
    setKeys((e) => {
      if (e.key !== "Enter") return;
      e.preventDefault();
      if (parseNumber(input.value) !== null) submit();
      else if (unreadable()) error.hidden = false;
    });
    async function submit() {
      const v = parseNumber(input.value);
      if (v === null) return;
      const canonical = canonNumber(v);
      const good = (await answerHash(s.id, canonical)) === K.answers[s.id];
      input.disabled = true;
      input.classList.add(good ? "is-good" : "is-bad");
      resolve({ good, idx, s, canonical, explainGood: s.explain, explainBad: s.explainWrong || s.explain });
    }
  }

  // match ----------------------------------------------------------------
  function matchStep(s, idx) {
    if (s.prompt) stageEl.append(el("p", { class: "body-text", html: s.prompt }));
    const shuffled = [...s.right].sort(() => Math.random() - 0.5);
    const left = el("div", { class: "col left" });
    const right = el("div", { class: "col right" });
    let selL = null, selR = null, mistakes = 0;
    const pairs = {};
    const mk = (side, item) => el("button", { class: "tile", "aria-pressed": "false", "data-id": item.id, onclick: (e) => choose(side, item.id, e.currentTarget) }, el("span", { html: item.html }));
    s.left.forEach((it) => left.append(mk("L", it)));
    shuffled.forEach((it) => right.append(mk("R", it)));
    stageEl.append(el("div", { class: "match" }, left, right));
    setFooter({ button: "Match all pairs", disabled: true });

    async function choose(side, id, node) {
      if (node.classList.contains("is-matched")) return;
      const col = side === "L" ? left : right;
      col.querySelectorAll(".tile").forEach((t) => t.setAttribute("aria-checked", "false"));
      node.setAttribute("aria-checked", "true");
      if (side === "L") selL = { id, node }; else selR = { id, node };
      if (!selL || !selR) return;
      const a = selL, b = selR;
      selL = selR = null;
      const ok = K.pairs[s.id].includes(await answerHash(s.id, `${a.id}:${b.id}`));
      a.node.setAttribute("aria-checked", "false");
      b.node.setAttribute("aria-checked", "false");
      if (ok) {
        pairs[a.id] = b.id;
        [a.node, b.node].forEach((n) => { n.classList.add("is-matched"); n.disabled = true; });
        if (Object.keys(pairs).length === s.left.length) {
          const canonical = Object.keys(pairs).sort().map((k) => `${k}:${pairs[k]}`).join(",");
          if (mistakes > 0) S.retried[idx] = true;
          resolve({ good: true, idx, s, canonical, explainGood: s.explain });
        }
      } else {
        mistakes += 1;
        [a.node, b.node].forEach((n) => {
          n.classList.remove("is-flash"); void n.offsetWidth; n.classList.add("is-flash");
          setTimeout(() => n.classList.remove("is-flash"), 600);
        });
      }
    }
  }

  // ---------------------------------------------------------------- finish
  async function unlockWord() {
    const material = `${S.cnetid}|` + K.order.map((q) => `${q}=${S.solved[q]}`).join("&");
    const entry = K.table[await idHash(S.cnetid)];
    if (!entry) return { error: "unknown" };
    if (K.order.some((q) => S.solved[q] === undefined)) return { error: "incomplete" };
    try {
      const base = await crypto.subtle.importKey("raw", enc.encode(material), "PBKDF2", false, ["deriveKey"]);
      const key = await crypto.subtle.deriveKey(
        { name: "PBKDF2", hash: "SHA-256", salt: enc.encode(`${K.salt}|${S.cnetid}`), iterations: K.iter },
        base, { name: "AES-GCM", length: 256 }, false, ["decrypt"]);
      const raw = b64(entry);
      const plain = await crypto.subtle.decrypt({ name: "AES-GCM", iv: raw.slice(0, 12) }, key, raw.slice(12));
      return { word: new TextDecoder().decode(plain) };
    } catch {
      return { error: "decrypt" };
    }
  }

  async function finish() {
    setKeys(null);
    if (!S.finishedAt) { S.finishedAt = Date.now(); save(); }
    app.innerHTML = "";
    const wrap = el("main", { class: "intro finish" });
    app.append(wrap);
    if (L.finishVisual) {
      const v = el("div", { class: "finish-visual" });
      wrap.append(v);
      mountVisual(v, L.finishVisual, { setReady() {}, math });
    }
    const total = questionIds.length;
    const minutes = Math.max(1, Math.round((S.finishedAt - S.startedAt) / 60000));
    wrap.append(
      el("div", { class: "kicker" }, L.kicker),
      el("h1", {}, "Tutorial complete"),
      el("p", { class: "lede" }, L.finishLine || "You're ready for class."),
      el("div", { class: "finish-stats" }, `${S.firstTry} of ${total} questions right on the first try · ${minutes} ${minutes === 1 ? "minute" : "minutes"}`),
    );
    const box = el("div", { class: "magic", "aria-live": "polite" }, el("div", { class: "label" }, "Unlocking your magic word…"));
    wrap.append(box);
    const res = S.word ? { word: S.word } : await unlockWord();
    box.innerHTML = "";
    if (res.word) {
      S.word = res.word; save();
      const copyBtn = el("button", { class: "btn ghost small", onclick: async () => {
        try { await navigator.clipboard.writeText(res.word); copyBtn.textContent = "Copied"; } catch { copyBtn.textContent = "Select and copy the word"; }
      } }, "Copy");
      box.append(
        el("div", { class: "label" }, `Magic word for ${S.cnetid}`),
        el("div", { class: "word" }, res.word),
        copyBtn);
      wrap.append(el("p", { class: "next", html: L.submitLine }));
      confetti();
    } else if (res.error === "unknown") {
      box.append(el("div", { class: "label" }, `We don't have a magic word for "${S.cnetid}".`));
      wrap.append(el("p", { class: "next" }, "Check the spelling of your CNetID and enter it again. If it's right, email the TA and we'll add you; your progress is saved."),
        el("div", { class: "row", style: "justify-content:center" }, el("button", { class: "btn", onclick: intro }, "Fix my CNetID")));
    } else {
      box.append(el("div", { class: "label" }, "Your word didn't unlock."));
      wrap.append(el("p", { class: "next" }, "This happens if the tutorial changed after you started. Start over to earn your word; it takes a few minutes."),
        el("div", { class: "row", style: "justify-content:center" }, el("button", { class: "btn", onclick: () => { S = fresh(S.cnetid); save(); shell(); step(); } }, "Start over")));
    }
    wrap.append(el("div", { class: "row", style: "justify-content:center;margin-top:18px" },
      el("button", { class: "linklike", onclick: intro }, "Back to the start page")));
    math(wrap);
  }

  function confetti() {
    if (reducedMotion()) return;
    const c = el("canvas", { style: "position:fixed;inset:0;pointer-events:none;z-index:20", "aria-hidden": "true" });
    document.body.append(c);
    const ctx = c.getContext("2d");
    const dpr = window.devicePixelRatio || 1;
    c.width = innerWidth * dpr; c.height = innerHeight * dpr; ctx.scale(dpr, dpr);
    const parts = Array.from({ length: 140 }, () => ({
      x: innerWidth / 2 + (Math.random() - 0.5) * 120, y: innerHeight * 0.35,
      vx: (Math.random() - 0.5) * 12, vy: -Math.random() * 13 - 4,
      r: Math.random() * Math.PI, vr: (Math.random() - 0.5) * 0.3,
      w: 6 + Math.random() * 6, h: 8 + Math.random() * 8, c: CONFETTI[Math.floor(Math.random() * CONFETTI.length)],
    }));
    const t0 = performance.now();
    (function frame(t) {
      ctx.clearRect(0, 0, innerWidth, innerHeight);
      for (const p of parts) {
        p.vy += 0.35; p.x += p.vx; p.y += p.vy; p.r += p.vr; p.vx *= 0.99;
        ctx.save(); ctx.translate(p.x, p.y); ctx.rotate(p.r); ctx.fillStyle = p.c; ctx.fillRect(-p.w / 2, -p.h / 2, p.w, p.h); ctx.restore();
      }
      if (t - t0 < 2600) requestAnimationFrame(frame); else c.remove();
    })(t0);
  }

  // ---------------------------------------------------------------- boot
  if (!window.crypto || !crypto.subtle) {
    app.innerHTML = '<main class="intro"><h1>Open this page over https</h1><p class="lede">Your browser blocks the security features this tutorial needs on this address. Use the course link on Canvas.</p></main>';
    return;
  }
  intro();
})();
